gai2(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0648 \u067e\u0632\u06cc\u0634\u06a9 \u0632\u06cc\u0627\u062f/\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc \u0628\u06a9\u0627\u062a\u060c \u0646\u0631\u062e\u06cc \u067e\u0632\u06cc\u0634\u06a9 \u062f\u06cc\u0627\u0631\u06cc \u0628\u06a9\u0627\u062a\u060c \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646 \u067e\u06d5\u0633\u06d5\u0646\u062f \u0628\u06a9\u0627\u062a"},
