ga3h(){return"\u0646\u0627\u06a4"},
ga3e(){return"\u0631\u06d5\u0646\u06af (hex\u060c \u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 FFB8763F)"},
ga1O(){return"\u062c\u06c6\u0631\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646"},
